import java.time.LocalDate;

public record Effectivity(LocalDate from, LocalDate until) {   // until == null -> open
    public boolean contains(LocalDate asOf) {
        return !asOf.isBefore(from) && (until == null || asOf.isBefore(until));
    }
}
